    #[test]
    fn setjmp_then_longjmp_restores_state() {
        let mut cpu = StubCpu::new();
        let mut kernel = fresh_kernel();
        cpu.map_region(0x1000, 0x1000, Prot::READ | Prot::WRITE)
            .unwrap();
        let t = dummy_thunk();
        let mut c = CallCtx {
            cpu: &mut cpu,
            thunk: &t,
            kernel: &mut kernel,
        };
        c.cpu.write_reg(ArmReg::R0, 0x1000).unwrap();
        c.cpu.write_reg(ArmReg::R4, 0xCAFE).unwrap();
        c.cpu.write_reg(ArmReg::Lr, 0xBADC0DE).unwrap();
        let _ = setjmp(&mut c).unwrap();
        // Trash registers so we can prove longjmp restores them.
        c.cpu.write_reg(ArmReg::R4, 0).unwrap();
        c.cpu.write_reg(ArmReg::Lr, 0).unwrap();
        c.cpu.write_reg(ArmReg::R0, 0x1000).unwrap();
        c.cpu.write_reg(ArmReg::R1, 42).unwrap();
        let r = longjmp(&mut c).unwrap();
        match r {
            DispatchOutcome::ReturnedR0(v) => assert_eq!(v, 42),
            _ => panic!(),
        }
        assert_eq!(c.cpu.read_reg(ArmReg::R4).unwrap(), 0xCAFE);
        assert_eq!(c.cpu.read_reg(ArmReg::Lr).unwrap(), 0xBADC0DE);
    }

    #[test]
    fn wcsrev_reverses_utf16_units_and_preserves_terminator_and_guard() {
        let mut cpu = StubCpu::new();
        let mut kernel = fresh_kernel();
        cpu.map_region(0x1000, 0x1000, Prot::READ | Prot::WRITE)
            .unwrap();
        let t = dummy_thunk();
        for units in [
            vec![0x41, 0xe9, 0x4e2d],
            vec![0xd83d, 0xde00],
            vec![0x78],
            vec![],
        ] {
            let mut input: Vec<u8> = units.iter().copied().flat_map(u16::to_le_bytes).collect();
            input.extend_from_slice(&[0, 0, 0xa5, 0x5a]);
            cpu.write_mem(0x1001, &input).unwrap();
            cpu.write_reg(ArmReg::R0, 0x1001).unwrap();
            let mut c = CallCtx {
                cpu: &mut cpu,
                thunk: &t,
                kernel: &mut kernel,
            };
            assert_eq!(wcsrev(&mut c).unwrap(), DispatchOutcome::ReturnedR0(0x1001));
            let mut expected: Vec<u8> =
                units.into_iter().rev().flat_map(u16::to_le_bytes).collect();
            expected.extend_from_slice(&[0, 0, 0xa5, 0x5a]);
            let actual = c.cpu.read_mem(0x1001, expected.len() as u32).unwrap();
            assert_eq!(actual, expected);
        }
    }

