        let (a, b, c) = (0x2000, 0x2004, 0x2008);
        let n = run_scanf(&mut cpu, &mut kernel, "12 -34 56", "%d %d %d", &[a, b, c]);
        assert_eq!(n, 3);
        assert_eq!(cpu.read_u32_le(a).unwrap(), 12);
        assert_eq!(cpu.read_u32_le(b).unwrap() as i32, -34);
