    /// A `CallCtx` over a stub CPU with one mapped scratch page, a
    /// distinct thunk per call site, and the argument registers set.
    ///
    /// `resolve_handler` memoizes by `thunk_va` including negative
    /// results, so every thunk a test builds needs its own address.
    fn thunk_at(va: u32) -> Thunk {
        let mut t = dummy_thunk();
        t.thunk_va = va;
        t
    }

    #[test]
    fn wide_case_folding_preserves_non_ascii_and_eof() {
        let mut cpu = StubCpu::new();
        let mut kernel = fresh_kernel();
        let t = dummy_thunk();
        let mut ctx = CallCtx {
            cpu: &mut cpu,
            kernel: &mut kernel,
            thunk: &t,
        };
        for (value, upper, lower) in [
            (0x61, 0x41, 0x61),
            (0x5a, 0x5a, 0x7a),
            (0, 0, 0),
            (0xe9, 0xe9, 0xe9),
            (0xffff, 0xffff, 0xffff),
            (u32::MAX, u32::MAX, u32::MAX),
        ] {
            ctx.cpu.write_reg(ArmReg::R0, value).unwrap();
            assert_eq!(
                towupper(&mut ctx).unwrap(),
                DispatchOutcome::ReturnedR0(upper)
            );
            ctx.cpu.write_reg(ArmReg::R0, value).unwrap();
            assert_eq!(
                towlower(&mut ctx).unwrap(),
                DispatchOutcome::ReturnedR0(lower)
            );
        }
    }

